import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Vlo documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"README.md"}'),d={name:"index.md"};function n(s,t,i,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? View /vlo/llms.txt for optimized Markdown documentation, or /vlo/llms-full.txt for full documentation bundle</div><h1 id="vlo-documentation" tabindex="-1">Vlo documentation <a class="header-anchor" href="#vlo-documentation" aria-label="Permalink to &quot;Vlo documentation&quot;">​</a></h1><p><strong>Durable execution for workflows and AI agents, as a library on the database you already run.</strong> Vlo keeps long-running work alive through crashes and restarts: an agent on its fortieth step, a render that takes three hours, an approval that takes two days.</p><table tabindex="0"><thead><tr><th></th><th>What you get</th><th>Read more</th></tr></thead><tbody><tr><td><strong>Tiny</strong></td><td>A 298 KB kernel inside your process. No cluster, no broker, no service to stand up.</td><td><a href="./why-vlo#tiny">Why Vlo</a></td></tr><tr><td><strong>Performant</strong></td><td>One transaction per step, and a resume that costs the same at 38 events and at 20,000.</td><td><a href="./performance">Performance</a></td></tr><tr><td><strong>Reliable</strong></td><td>Nothing is acknowledged before it is saved, and every checkpoint is hash-checked.</td><td><a href="./reliability">Reliability</a></td></tr><tr><td><strong>Efficient</strong></td><td>A waiting run holds no compute. An agent that reaches its budget parks instead of burning money.</td><td><a href="./why-vlo#efficient">Why Vlo</a></td></tr><tr><td><strong>Built for the edge</strong></td><td>A kernel with no I/O that runs anywhere wasm runs. The edge host is not built yet.</td><td><a href="./status">Status and roadmap</a></td></tr></tbody></table><p>All five come from one design principle: a workflow is a pure reducer, <code>(state, event) → (state, commands)</code>. An event comes in, new state and commands come out, and both are saved in one database transaction. Between events a run is only rows in your Postgres or a SQLite file, so nothing has to be kept alive, captured or replayed.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If you are</th><th>Start with</th></tr></thead><tbody><tr><td>New to Vlo</td><td><a href="./getting-started">Getting started</a>: a run on your laptop in ten minutes, then kill the process and watch it continue.</td></tr><tr><td>Building an AI agent</td><td><a href="./agent-harness">Build an agent harness</a>: a loop that survives crashes, stays inside a budget and waits for people.</td></tr><tr><td>Deciding whether to adopt it</td><td><a href="./why-vlo">Why Vlo</a>, then <a href="./performance">Performance</a>, <a href="./reliability">Reliability</a> and <a href="./status">Status and roadmap</a>.</td></tr><tr><td>Looking for a how-to</td><td><a href="./recipes">Recipes</a> and the <a href="./faq">FAQ</a>.</td></tr><tr><td>Taking it to production</td><td><a href="./deployment">Deployment</a>, <a href="./configuration">Configuration</a> and <a href="./limits">Limits</a>.</td></tr></tbody></table><h2 id="all-pages" tabindex="-1">All pages <a class="header-anchor" href="#all-pages" aria-label="Permalink to &quot;All pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Read it when</th></tr></thead><tbody><tr><td><strong>Evaluate</strong></td><td></td></tr><tr><td><a href="./why-vlo">Why Vlo</a></td><td>You want the argument: what durable execution costs today, what Vlo changes, and what it does not have yet.</td></tr><tr><td><a href="./performance">Performance</a></td><td>You want measured numbers, with their setup and their limits.</td></tr><tr><td><a href="./reliability">Reliability</a></td><td>You want to know exactly what Vlo guarantees and how.</td></tr><tr><td><a href="./status">Status and roadmap</a></td><td>You want to know what is built and what is planned.</td></tr><tr><td><a href="./faq">FAQ</a></td><td>You have an objection or a quick question.</td></tr><tr><td><strong>Build</strong></td><td></td></tr><tr><td><a href="./getting-started">Getting started</a></td><td>You want a run going on a laptop in ten minutes.</td></tr><tr><td><a href="./concepts">Concepts</a></td><td>You need the vocabulary: run, step, event, command, role, profile.</td></tr><tr><td><a href="./workflows">Workflows</a></td><td>You are writing a reducer, or using <code>sequence</code>, <code>fanOut</code>, <code>waitFor</code>, <code>sleep</code>.</td></tr><tr><td><a href="./activities-and-workers">Activities and workers</a></td><td>You are implementing the code a task runs, in-process or over HTTP.</td></tr><tr><td><a href="./signals-and-humans">Signals and humans</a></td><td>A run has to wait for a person, a webhook or a deadline.</td></tr><tr><td><a href="./agent-harness">Build an agent harness</a></td><td>You are building an agent end to end.</td></tr><tr><td><a href="./agents">Agents</a></td><td>You need the <code>@oona/vlo/agent</code> reference: options, step ids, state and result.</td></tr><tr><td><a href="./testing">Testing</a></td><td>You are testing a reducer, a workflow or an agent.</td></tr><tr><td><a href="./recipes">Recipes</a></td><td>You want a short answer to &quot;how do I…&quot;.</td></tr><tr><td><strong>Operate</strong></td><td></td></tr><tr><td><a href="./configuration">Configuration</a></td><td><code>vlo.config.ts</code>: profiles, queues, roles, dispatcher mode, <code>env()</code>.</td></tr><tr><td><a href="./cli">CLI</a></td><td><code>vlo dev</code>, <code>vlo serve</code>, <code>vlo doctor</code>, <code>vlo deploy</code>.</td></tr><tr><td><a href="./deployment">Deployment</a></td><td>Long-lived hosts, serverless hosts with a cron, pull workers.</td></tr><tr><td><a href="./observability">Observability</a></td><td>The journal as the trace, usage accounting, the side channel, health.</td></tr><tr><td><a href="./http-api">HTTP API</a></td><td>Every route, its auth, its JSON, the SSE stream, push and poll.</td></tr><tr><td><a href="./journal">Journal</a></td><td>The tables, the Postgres and SQLite adapters, blob stores, URL forms.</td></tr><tr><td><a href="./errors">Errors</a></td><td>Host errors, kernel error codes, <code>vlo doctor</code> hints and what to do.</td></tr><tr><td><a href="./limits">Limits</a></td><td>Payload caps, size budgets, known weak spots, what edge runtimes cannot do yet.</td></tr><tr><td><strong>Internals</strong></td><td></td></tr><tr><td><a href="./architecture">Architecture</a></td><td>Layers, the write path, the task lifecycle, how roles split across processes.</td></tr><tr><td><a href="./kernel-protocol">Kernel protocol</a></td><td>The JSON-in / JSON-out contract between host and kernel, hashing, fixtures.</td></tr><tr><td><a href="./design-decisions">Design decisions</a></td><td>Why a reducer, why the journal is the queue, why Rust on wasm.</td></tr></tbody></table><h2 id="generated-api-reference" tabindex="-1">Generated API reference <a class="header-anchor" href="#generated-api-reference" aria-label="Permalink to &quot;Generated API reference&quot;">​</a></h2><p>Both are published with these pages at <a href="https://oonalab.github.io/vlo/" target="_blank" rel="noreferrer">https://oonalab.github.io/vlo/</a>.</p><ul><li><strong>TypeScript</strong> (<code>@oona/vlo</code> and its <code>/host</code>, <code>/agent</code> and <code>/testing</code> entries): <a href="https://oonalab.github.io/vlo/api/" target="_blank" rel="noreferrer">oonalab.github.io/vlo/api/</a>. TypeDoc writes a page for every exported symbol into <code>docs/api/</code>. Build it locally with <code>pnpm --filter @oona/vlo docs:api</code>; the output is not committed, so you will not find it in a checkout.</li><li><strong>Rust</strong> (<code>vlo-types</code>, <code>vlo-kernel</code>, <code>vlo-kernel-wasm</code>, <code>vlo-traits</code>): <a href="https://oonalab.github.io/vlo/rustdoc/" target="_blank" rel="noreferrer">oonalab.github.io/vlo/rustdoc/</a>. Build it locally with <code>cargo doc --workspace --no-deps --open</code> from the repository root.</li></ul><h2 id="conventions-used-in-these-pages" tabindex="-1">Conventions used in these pages <a class="header-anchor" href="#conventions-used-in-these-pages" aria-label="Permalink to &quot;Conventions used in these pages&quot;">​</a></h2><ul><li>Paths are relative to the repository root unless they start with <code>src/</code>, in which case they are relative to <code>sdk/ts/sdk/</code>.</li><li>Wire fields are <code>snake_case</code> (<code>cost_micro_usd</code>); authoring options are <code>camelCase</code> (<code>costMicroUsd</code>). The wire form is what you see in the journal and on the HTTP API.</li><li>Every instant is a millisecond Unix epoch and every such column or field ends in <code>_ms</code>.</li></ul>',14)])])}const f=e(d,[["render",n]]);export{p as __pageData,f as default};
